class LeakAwareEmitter {
  readonly #listeners = new Map<string, Array<() => void>>();
  readonly warnings: string[] = [];

  constructor(private readonly max: number) {}

  on(name: string, listener: () => void): void {
    const list = this.#listeners.get(name) ?? [];
    list.push(listener);
    this.#listeners.set(name, list);
    if (list.length === this.max + 1) this.warnings.push(`possible leak: ${list.length} listeners for ${name}`);
  }
}

const emitter = new LeakAwareEmitter(3);
for (let request = 1; request <= 5; request++) emitter.on("order.placed", () => {});
emitter.on("stock.low", () => {});
console.log(emitter.warnings.join("\n") || "no warnings");
